import { expect, test, type Page } from '@playwright/test';
import { readFileSync } from 'node:fs';
import type { TrainingAnalytics } from '../../src/shared/api/types';
import { installPlatformApi } from './fixtures/platform-api';

type FixtureState = 'populated' | 'incomplete' | 'empty' | 'all_unmapped';
// Generated by the existing analytics service, with canonical catalogue links.
const { snapshots } = JSON.parse(
  readFileSync(
    new URL('../../../docs/ux-proposals/issue-827-v12/fixtures.json', import.meta.url),
    'utf8',
  ),
) as { snapshots: Record<FixtureState, Record<string, TrainingAnalytics>> };

const analyticsPath = '/workouts/progress/training-analytics';
const workload = (page: Page) => page.getByRole('region', { name: 'Мышечные группы', exact: true });
const group = (page: Page, name: string) =>
  workload(page).getByRole('button', { name: new RegExp(`^${name} `) });

async function openTraining(page: Page) {
  await page.goto('/app?section=progress&progress_view=training&progress_period=days_7');
  await page.getByRole('button', { name: 'Клиент', exact: true }).click();
  await expect(page.locator('#progress-training')).toBeVisible();
}

async function mockAnalytics(page: Page, state: FixtureState = 'populated') {
  await installPlatformApi(page, { fixedDate: '2026-10-30' });
  await page.route('**/workouts/progress/activity-heatmap**', (route) => {
    const year = Number(new URL(route.request().url()).searchParams.get('year'));
    const days = (Date.UTC(year + 1, 0, 1) - Date.UTC(year, 0, 1)) / 86_400_000;
    return route.fulfill({
      json: {
        timezone: 'Europe/Moscow',
        history_complete: false,
        undated_workouts: 0,
        days: Array.from({ length: days }, (_, index) => ({
          date: new Date(Date.UTC(year, 0, index + 1)).toISOString().slice(0, 10),
          is_future: false,
          completed_workouts: null,
          working_sets: null,
        })),
      },
    });
  });
  await page.route(`**${analyticsPath}**`, (route) => {
    const days = new URL(route.request().url()).searchParams.get('period_days')!;
    expect(['7', '30', '90']).toContain(days);
    return route.fulfill({ json: snapshots[state][days] });
  });
}

test('#827 switches 7/30/90 API periods and shows their distinct facts without replacing #835 calendar', async ({
  page,
}) => {
  await mockAnalytics(page);
  const requestedPeriods: string[] = [];
  let calendarRequests = 0;
  page.on('request', (request) => {
    const url = new URL(request.url());
    if (url.pathname.endsWith(analyticsPath))
      requestedPeriods.push(url.searchParams.get('period_days')!);
    if (url.pathname.endsWith('/workouts/progress/activity-heatmap')) calendarRequests += 1;
  });
  await openTraining(page);
  const training = page.locator('#progress-training');
  await expect(
    page.locator('.activity-heatmap').getByRole('heading', { name: /^Активность/ }),
  ).toBeVisible();
  for (const [days, sets, chestSets] of [
    [7, 36, 16],
    [30, 48, 22],
    [90, 60, 28],
  ] as const) {
    if (days !== 7) {
      const request = page.waitForRequest((item) => {
        const url = new URL(item.url());
        return (
          url.pathname.endsWith(analyticsPath) &&
          url.searchParams.get('period_days') === String(days)
        );
      });
      await page
        .locator('.progress-hero')
        .getByRole('tab', { name: `${days} дней`, exact: true })
        .click();
      await request;
    }
    await expect(
      page.locator('.progress-hero').getByRole('tab', { name: `${days} дней`, exact: true }),
    ).toHaveAttribute('aria-selected', 'true');
    await expect(training.getByRole('definition').first()).toHaveText(String(sets));
    await expect(group(page, 'Грудь')).toContainText(`Всего ${chestSets}`);
    await group(page, 'Грудь').click();
    const detail = workload(page).getByRole('region', { name: 'Грудь', exact: true });
    await expect(detail).toContainText(`Текущие ${days} дней`);
    await expect(detail).toContainText(`Предыдущие ${days} дней`);
    await expect(detail.locator('.muscle-distribution__comparison > div').first()).toContainText(
      `${chestSets} подх.`,
    );
  }
  expect(requestedPeriods).toEqual(['7', '30', '90']);
  expect(calendarRequests).toBe(1);
  await expect(page.locator('.activity-heatmap')).toHaveCount(1);
});

test('#827 keyboard selection preserves role counts, source disclosures and unknown versus zero', async ({
  page,
}) => {
  await mockAnalytics(page);
  await openTraining(page);
  const chest = group(page, 'Грудь');
  await chest.focus();
  await chest.press('Enter');
  await expect(chest).toBeFocused();
  await expect(chest).toHaveAttribute('aria-pressed', 'true');
  await expect(workload(page).getByRole('button', { pressed: true })).toHaveCount(1);
  await expect(chest).toHaveAccessibleName(/Всего 16 Основное 8 Вспомогательное 8/);
  const detail = workload(page).getByRole('region', { name: 'Грудь', exact: true });
  await expect(detail).toContainText('Изменение: +10 подходов');
  const primary = detail.locator('details').filter({ hasText: 'Жим лежа' });
  await expect(primary).toContainText('Основное участие');
  await expect(primary).toContainText('8 подходов · 2 тренировки');
  const source = primary.locator(':scope > summary');
  await source.focus();
  await source.press('Enter');
  await expect(primary).toHaveAttribute('open', '');
  await expect(primary.locator('li')).toHaveCount(2);
  await expect(primary.locator('li').first()).toContainText('4 подхода');
  await source.press('Enter');
  await expect(primary).not.toHaveAttribute('open');
  const secondary = detail.locator('details').filter({ hasText: 'Пуловер в тренажёре' });
  await expect(secondary).toContainText('Вспомогательное участие');
  await expect(secondary).toContainText('8 подходов · 2 тренировки');

  const calves = group(page, 'Икры');
  await calves.focus();
  await calves.press('Space');
  await expect(calves).toBeFocused();
  await expect(calves).toHaveAttribute('aria-pressed', 'true');
  await expect(chest).toHaveAttribute('aria-pressed', 'false');
  await expect(calves).toContainText('Нет данных');
  await expect(calves).not.toContainText('Всего 0');
  const nullDetail = workload(page).getByRole('region', { name: 'Икры', exact: true });
  await expect(nullDetail.locator('.muscle-distribution__comparison > div').first()).toContainText(
    'Нет данных',
  );
  await expect(nullDetail.locator('.muscle-distribution__comparison > div').last()).toContainText(
    '3 подх.',
  );
  await expect(nullDetail).toContainText('Нет данных для сравнения');

  await group(page, 'Спина').click();
  await expect(workload(page).getByRole('region', { name: 'Спина', exact: true })).toContainText(
    'Нет данных для сравнения',
  );
  await expect(page.locator('#progress-training').getByRole('definition').first()).toHaveText('36');
  await expect(workload(page)).toContainText(
    'Значения групп не складываются в общее число подходов.',
  );
  await expect(
    page.locator('#progress-training .progress-exercises').getByText('Жим лежа', { exact: true }),
  ).toBeVisible();
  const methodology = page.locator('#progress-methodology');
  await methodology.locator(':scope > summary').click();
  await expect(methodology).toContainText(
    'Подход отдельно учитывается для каждой явно связанной основной и дополнительной мышечной группы.',
  );
});

for (const state of ['incomplete', 'empty', 'all_unmapped'] as const) {
  test(`#827 ${state} never converts missing muscle metadata into untrained groups`, async ({
    page,
  }) => {
    await mockAnalytics(page, state);
    await openTraining(page);
    const distribution = workload(page);
    await expect(distribution).toBeVisible();
    await expect(page.locator('#progress-training').getByRole('definition').first()).toHaveText(
      String(snapshots[state]['7']!.completed_set_count),
    );
    if (state === 'incomplete') {
      await expect(distribution).toContainText('2 подхода без мышечных связей.');
      await expect(group(page, 'Грудь')).toContainText('Всего 16');
      await expect(distribution).toContainText(
        'Они входят в общее число подходов, но не распределены по группам.',
      );
    } else {
      await expect(distribution.getByRole('button')).toHaveCount(0);
      await expect(distribution.locator('.muscle-distribution__track')).toHaveCount(0);
      await expect(distribution).toContainText(
        state === 'empty' ? 'Нет записанных подходов' : 'Распределение пока недоступно',
      );
      if (state === 'all_unmapped') {
        await expect(distribution).toContainText('6 подходов без мышечных связей.');
        await expect(distribution).toContainText(
          'Отсутствие связей не означает, что мышцы не участвовали.',
        );
      } else {
        await expect(distribution.locator('.muscle-distribution__notice')).toHaveCount(0);
      }
    }
  });
}

test('#827 loading and failed analytics expose a working retry without stale muscle facts', async ({
  page,
}) => {
  await installPlatformApi(page, { fixedDate: '2026-10-30' });
  let release!: () => void;
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  let recover = false;
  let calls = 0;
  await page.route(`**${analyticsPath}**`, async (route) => {
    calls += 1;
    await gate;
    return recover
      ? route.fulfill({ json: snapshots.populated['7'] })
      : route.fulfill({ status: 503, json: { detail: 'История временно недоступна' } });
  });
  await openTraining(page);
  const training = page.locator('#progress-training');
  await expect(training.getByRole('status')).toContainText('Собираем историю тренировок…');
  await expect(workload(page)).toHaveCount(0);
  release();
  const error = training.getByRole('alert');
  await expect(error).toContainText('Сервис временно недоступен. Попробуйте ещё раз.');
  await expect(workload(page)).toHaveCount(0);
  const failedCalls = calls;
  recover = true;
  const response = page.waitForResponse((item) => item.url().includes(analyticsPath) && item.ok());
  await error.getByRole('button', { name: 'Повторить', exact: true }).click();
  await response;
  await expect(group(page, 'Грудь')).toContainText('Всего 16');
  await expect(error).toHaveCount(0);
  expect(calls).toBe(failedCalls + 1);
});
